#include <vector>
using namespace std;

class Solution {
public:
    vector<bool> canEat(vector<int>& candiesCount, vector<vector<int>>& queries) {
        int n = candiesCount.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + candiesCount[i];

        vector<bool> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            int fav_type = q[0];
            long long fav_day = q[1];
            long long daily_cap = q[2];
            long long min_candies = fav_day + 1;
            long long max_candies = (fav_day + 1) * daily_cap;
            long long type_start = pref[fav_type] + 1;
            long long type_end = pref[fav_type + 1];
            ans.push_back(!(max_candies < type_start || min_candies > type_end));
        }
        return ans;
    }
};

class Solution {
    public boolean[] canEat(int[] candiesCount, int[][] queries) {
        int n = candiesCount.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + candiesCount[i];

        boolean[] ans = new boolean[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int favType = queries[i][0];
            long favDay = queries[i][1];
            long dailyCap = queries[i][2];
            long minCandies = favDay + 1;
            long maxCandies = (favDay + 1) * dailyCap;
            long typeStart = pref[favType] + 1;
            long typeEnd = pref[favType + 1];
            ans[i] = !(maxCandies < typeStart || minCandies > typeEnd);
        }
        return ans;
    }
}

/**
 * @param {number[]} candiesCount
 * @param {number[][]} queries
 * @return {boolean[]}
 */
var canEat = function(candiesCount, queries) {
    const n = candiesCount.length;
    const pref = Array(n + 1).fill(0);
    for (let i = 0; i < n; ++i) pref[i + 1] = pref[i] + candiesCount[i];

    const ans = [];
    for (const [favType, favDay, dailyCap] of queries) {
        const minCandies = favDay + 1;
        const maxCandies = (favDay + 1) * dailyCap;
        const typeStart = pref[favType] + 1;
        const typeEnd = pref[favType + 1];
        ans.push(!(maxCandies < typeStart || minCandies > typeEnd));
    }
    return ans;
};
